-- Supabase catalog entry for Electrostatics quiz v1.
insert into public.study_tests(id,title,subject,grade,level,path,questions) values ('elektrostatyka-iga-v1','Elektrostatyka: Ładunek!','Fizyka','2lo','podstawowy','testy/fizyka/elektrostatyka-igi.html','[{"no":1,"question":"Co może przechodzić z jednego ciała na drugie podczas elektryzowania przez tarcie?","topic":"Elektryzowanie","options":["Protony znajdujące się w jądrach atomów","Elektrony","Neutrony","Całe jądra atomowe"],"correct":1,"explanation":"W typowych doświadczeniach z tarciem przenoszone są elektrony. Protony pozostają w jądrach atomowych."},{"no":2,"question":"Co oznacza, że balonik został naelektryzowany ujemnie?","topic":"Znaki ładunków","options":["Ma nadmiar elektronów","Utracił wszystkie protony","Ma niedobór elektronów","Nie ma żadnego ładunku"],"correct":0,"explanation":"Ujemny ładunek oznacza nadmiar elektronów w stosunku do protonów."},{"no":3,"question":"Co się stanie, jeśli zbliżymy dwie kulki naładowane dodatnio?","topic":"Oddziaływanie ładunków","options":["Zawsze się połączą","Przyciągną się","Odepchną się","Przestaną mieć ładunek"],"correct":2,"explanation":"Ładunki jednoimienne się odpychają, a różnoimienne się przyciągają."},{"no":4,"question":"Który zestaw zawiera odpowiednio przewodnik i izolator?","topic":"Przewodniki i izolatory","options":["Szkło – miedź","Guma – aluminium","Miedź – sucha guma","Styropian – srebro"],"correct":2,"explanation":"Miedź przewodzi prąd dzięki swobodnym elektronom. Sucha guma jest izolatorem."},{"no":5,"question":"Dlaczego naelektryzowany balonik może przyciągać obojętne elektrycznie skrawki papieru?","topic":"Polaryzacja","options":["Papier zawsze ma ładunek ujemny","Balonik silnie zwiększa grawitację","W papierze zachodzi polaryzacja ładunków","Każdy skrawek papieru staje się magnesem"],"correct":2,"explanation":"Pole balonika nieznacznie przemieszcza ładunki związane w papierze. Bliższa część jest silniej przyciągana, choć cały papier pozostaje obojętny."},{"no":6,"question":"Co dzieje się w metalowym, początkowo obojętnym przedmiocie, gdy zbliżamy do niego naładowany pręt bez dotykania?","topic":"Indukcja elektrostatyczna","options":["Ładunki w metalu rozdzielają się","Wszystkie protony odpływają z metalu","Wszystkie elektrony znikają","Metal bezwzględnie uzyskuje nowy ładunek całkowity"],"correct":0,"explanation":"Indukcja powoduje rozdział ładunków w przewodniku, lecz bez uziemienia nie musi zmienić jego ładunku całkowitego."},{"no":7,"question":"Dwie identyczne metalowe kulki: jedna ma ładunek +8 nC, druga jest obojętna. Po zetknięciu i rozdzieleniu ich ładunki wynoszą:","topic":"Elektryzowanie przez dotyk","options":["+8 nC i 0 nC","+4 nC i +4 nC","+8 nC i +8 nC","+4 nC i −4 nC"],"correct":1,"explanation":"Ładunek całkowity jest zachowany (+8 nC). Identyczne kulki po zetknięciu dzielą go po równo: każda ma +4 nC."},{"no":8,"question":"Odległość dwóch punktowych ładunków zwiększono dwukrotnie. Jak zmieniła się siła elektrostatyczna?","topic":"Prawo Coulomba","options":["Wzrosła 2 razy","Zmalała 2 razy","Zmalała 4 razy","Nie zmieniła się"],"correct":2,"explanation":"Prawo Coulomba: F = k·|q₁q₂|/r². Podwojenie odległości powoduje czterokrotne zmniejszenie siły."},{"no":9,"question":"Odległość między dwoma ładunkami wzrosła z 2 cm do 6 cm. Ile razy zmalała siła oddziaływania?","topic":"Prawo Coulomba","options":["3 razy","6 razy","9 razy","18 razy"],"correct":2,"explanation":"Odległość wzrosła 3 razy, więc siła zmalała 3², czyli 9 razy."},{"no":10,"question":"Ładunki +1 nC i −2 nC są oddalone o 0,2 m. Ile wynosi wartość siły? Przyjmij k = 9·10⁹ N·m²/C².","topic":"Obliczanie siły","options":["4,5·10⁻⁷ N","4,5·10⁻⁵ N","9·10⁻³ N","2·10⁻⁷ N"],"correct":0,"explanation":"F = 9·10⁹·(1·10⁻⁹·2·10⁻⁹)/(0,2)² = 4,5·10⁻⁷ N. Ładunki przyciągają się."},{"no":11,"question":"Jaką jednostkę ma ładunek elektryczny w układzie SI?","topic":"Ładunek i jednostki","options":["Niuton (N)","Kulomb (C)","Wolt (V)","Dżul (J)"],"correct":1,"explanation":"Ładunek mierzymy w kulombach (C), a siłę w niutonach (N)."},{"no":12,"question":"W którym kierunku zwrócone są linie pola elektrycznego między ładunkiem dodatnim i ujemnym?","topic":"Pole elektryczne","options":["Od minusa do plusa","Od plusa do minusa","Prostopadle do obu ładunków","Zawsze w kierunku pionowym"],"correct":1,"explanation":"Zwrot linii pola jest zgodny z siłą działającą na dodatni ładunek próbny: od plusa do minusa."},{"no":13,"question":"Na rysunku w pewnym obszarze linie pola są gęściej rozmieszczone niż w innym. Oznacza to:","topic":"Natężenie pola","options":["Silniejsze pole elektryczne","Słabsze pole elektryczne","Większą masę ładunków","Brak jakiejkolwiek siły"],"correct":0,"explanation":"Większe zagęszczenie linii jest umownym oznaczeniem większego natężenia pola."},{"no":14,"question":"Gdzie w przybliżeniu można uzyskać jednorodne pole elektryczne?","topic":"Pole jednorodne","options":["Wokół punktowego ładunku dodatniego","Między dwiema dużymi równoległymi płytami o przeciwnych ładunkach, z dala od krawędzi","Przy dowolnym jednym baloniku","Tylko podczas burzy"],"correct":1,"explanation":"Między równoległymi płytami pole jest w środkowym obszarze niemal jednorodne: linie są równoległe i równomiernie rozłożone."},{"no":15,"question":"Dlaczego listki naelektryzowanego elektroskopu rozchylają się?","topic":"Elektroskop","options":["Nabierają ładunków tego samego znaku i się odpychają","Zaczynają być magnetyczne","Tracą masę","Przyciąga je metalowa obudowa"],"correct":0,"explanation":"Listki zyskują ładunki jednoimienne, dlatego działa między nimi siła odpychania."},{"no":16,"question":"Na czym polega uziemienie naelektryzowanego metalowego przedmiotu?","topic":"Uziemienie","options":["Na zamianie elektronów w protony","Na ogrzaniu go do wysokiej temperatury","Na umożliwieniu przepływu ładunku między przedmiotem a Ziemią","Na całkowitym usunięciu wszystkich elektronów"],"correct":2,"explanation":"Uziemienie umożliwia przepływ ładunku do lub z Ziemi i często prowadzi do rozładowania przedmiotu."},{"no":17,"question":"Czym jest piorun?","topic":"Wyładowania atmosferyczne","options":["Nagłym wyładowaniem elektrycznym w atmosferze","Falą dźwiękową bez elektryczności","Strumieniem gorącego powietrza bez ładunków","Światłem odbitym od chmur"],"correct":0,"explanation":"Piorun to gwałtowne wyładowanie elektryczne, które może zachodzić w chmurze, między chmurami albo między chmurą a ziemią."},{"no":18,"question":"Gdzie najlepiej schronić się podczas burzy?","topic":"Bezpieczeństwo podczas burzy","options":["Pod samotnym wysokim drzewem","W jeziorze, możliwie blisko brzegu","Na odkrytym wzniesieniu","W solidnym budynku lub zamkniętym samochodzie"],"correct":3,"explanation":"Podczas burzy bezpieczniej schronić się w solidnym budynku lub zamkniętym samochodzie z metalowym nadwoziem. Unikamy drzew, otwartego terenu i wody."}]'::jsonb) on conflict (id) do nothing;
